// ---------------------------------------------------------------
// UpdateCustomerWF - Prepare Request
//
// Design intent (CLAUDE.md Phase 2 + §3.4):
//   - db-api is the single authoritative auth boundary.
//     This node does NOT enforce JWT presence; it proxies whatever the
//     caller sent. db-api (@fastify/jwt) returns a clean 401 on invalid
//     or missing tokens, so there's no value in throwing here too.
//   - tenant_id is NEVER read from body — db-api derives it from the JWT.
//   - UUID shape-check only; db-api's ajv schema is the authority.
//
// Why we do NOT default a placeholder token (e.g. "Bearer TEST_MODE"):
//   - db-api will reject any unsigned string → same 401, one hop later.
//   - A hard-coded token literal in production JSON looks like a
//     backdoor in code review and becomes one the day someone adds a
//     matching short-circuit to the API.
// ---------------------------------------------------------------
const input   = $input.first().json || {};
const body    = input.body    || {};
const headers = input.headers || {};

const customerId = body.customer_id;
if (!customerId) {
  throw new Error('customer_id is required');
}
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_RE.test(customerId)) {
  throw new Error('customer_id must be a valid UUID');
}

// JWT body-tunnel: frontend cannot send Authorization header (CORS preflight
// restriction), so it embeds the raw token in body.jwt instead.
// Priority: header (direct API calls / Postman) → body.jwt (browser frontend).
const rawToken = headers.authorization || headers.Authorization || body.jwt || '';
const auth = rawToken.startsWith('Bearer ') ? rawToken : (rawToken ? 'Bearer ' + rawToken : '');

// Whitelisted payload. db-api uses COALESCE(NULLIF($n,''), col) so empty
// strings mean "leave column unchanged" (see CLAUDE.md Step 2.4).
return [{
  json: {
    authorization: auth,
    payload: {
      customer_id: customerId,
      full_name:   body.full_name  ?? '',
      email:       body.email      ?? '',
      phone:       body.phone      ?? '',
      event_type:  body.event_type ?? '',
      notes:       body.notes      ?? ''
    }
  }
}];
